                    tag = "request_review"
                    body = JsonObject(emptyMap())
                }
                is Navree.ReplyCall.Unknown -> {
                    tag = value.tag
                    val kept = LinkedHashMap<String, JsonElement>()
                    body = JsonObject(kept)
                }
            }
            output.encodeJsonElement(JsonObject(mapOf("f" to JsonPrimitive(tag)) + body))
