    /** `When`: one of its variants, told apart by `t`. */
    @Serializable(with = Navree.WhenSerializer::class)
    public sealed interface When {
        /** `When.At`. */
        @Serializable
        public data class At(
            val unix: Long,
        ) : Navree.When
        /** `When.After`. */
        @Serializable
        public data class After(
            val secs: Long,
        ) : Navree.When
        /** `When.Daily`. */
        @Serializable
        public data class Daily(
            val hour: Int,
            val minute: Int,
        ) : Navree.When
        /** A variant this build does not know, from a newer server, with what it keeps. */
        public data class Unknown(
            val tag: String,
        ) : Navree.When
    }

    /** Reads and writes a [When] by its `t`. */
    public object WhenSerializer : KSerializer<Navree.When> {
        override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

        override fun deserialize(decoder: Decoder): Navree.When {
            val input = decoder as JsonDecoder
            val fields = input.decodeJsonElement() as? JsonObject ?: return Navree.When.Unknown(tag = "")
            val tag = (fields["t"] as? JsonPrimitive)?.contentOrNull
            val body = JsonObject(fields.filterKeys { it != "t" })
            return when (tag) {
                "at" -> input.json.decodeFromJsonElement(Navree.When.At.serializer(), body)
                "after" -> input.json.decodeFromJsonElement(Navree.When.After.serializer(), body)
                "daily" -> input.json.decodeFromJsonElement(Navree.When.Daily.serializer(), body)
                else -> Navree.When.Unknown(
                    tag = tag ?: "",
                )
            }
        }

        override fun serialize(encoder: Encoder, value: Navree.When) {
            val output = encoder as JsonEncoder
            val tag: String
            val body: JsonObject
            when (value) {
                is Navree.When.At -> {
                    tag = "at"
                    body = output.json.encodeToJsonElement(Navree.When.At.serializer(), value) as JsonObject
                }
                is Navree.When.After -> {
                    tag = "after"
                    body = output.json.encodeToJsonElement(Navree.When.After.serializer(), value) as JsonObject
                }
                is Navree.When.Daily -> {
                    tag = "daily"
                    body = output.json.encodeToJsonElement(Navree.When.Daily.serializer(), value) as JsonObject
                }
                is Navree.When.Unknown -> {
                    tag = value.tag
                    val kept = LinkedHashMap<String, JsonElement>()
                    body = JsonObject(kept)
                }
            }
            output.encodeJsonElement(JsonObject(mapOf("t" to JsonPrimitive(tag)) + body))
        }
